mapper.select:
/* 마케팅 프로젝트 목록 조회 marketing.selectMarketingProjectList */ SELECT p.MKT_PROJECT_ID AS MARKETING_PROJECT_ID , p.PROJECT_NM AS PROJECT_NM , p.ORG_NM AS ORG_NM , p.PROJECT_OVERVIEW AS PROJECT_OVERVIEW , DATE_FORMAT(p.DUE_DT, '%Y-%m-%d') AS DUE_DT , p.STATUS_CD AS STATUS_CD , cd.CODE_NM AS STATUS_NM , CAST(p.PROJECT_CONFIG_JSON AS CHAR) AS PROJECT_CONFIG_JSON , p.CREATE_USER_ID AS CREATE_USER_ID , DATE_FORMAT(p.CREATE_DT, '%Y-%m-%d %H:%i:%s') AS CREATE_DT , p.MODIFY_USER_ID AS MODIFY_USER_ID , DATE_FORMAT(p.MODIFY_DT, '%Y-%m-%d %H:%i:%s') AS MODIFY_DT FROM TB_MKT_PROJECT p LEFT JOIN TB_CODE cd ON cd.CODE_GRP_ID = 'PT000002' AND cd.CODE_ID = p.STATUS_CD WHERE 1 = 1
AND p.STATUS_CD = #{statusCd}
AND ( p.PROJECT_NM LIKE CONCAT('%', #{keyword}, '%') OR p.ORG_NM LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY
p.CREATE_DT p.DUE_DT COALESCE(p.MODIFY_DT, p.CREATE_DT)
ASC DESC
LIMIT #{limit}
OFFSET #{offset}

mapper.insert:
/* 마케팅 프로젝트 등록 marketing.insertMarketingProject */
INSERT INTO TB_MKT_PROJECT (
    MKT_PROJECT_ID
    , PROJECT_NM
    , ORG_NM
    , PROJECT_OVERVIEW
    , DUE_DT
    , STATUS_CD
    , PROJECT_CONFIG_JSON
    , CREATE_USER_ID
    , CREATE_DT
) VALUES (
    #{marketingProjectId}
    , #{projectNm}
    , #{orgNm}
    , #{projectOverview}
    , #{dueDt}
    , #{statusCd}
    , #{projectConfigJson}
    , #{createUserId}
    , NOW()
)

mapper.update:
/* 마케팅 프로젝트 수정 marketing.updateMarketingProject */
UPDATE TB_MKT_PROJECT SET
    PROJECT_NM          = #{projectNm}
    , ORG_NM             = #{orgNm, jdbcType=VARCHAR}
    , PROJECT_OVERVIEW   = #{projectOverview, jdbcType=VARCHAR}
    , DUE_DT             = #{dueDt, jdbcType=DATE}
    , PROJECT_CONFIG_JSON = #{projectConfigJson, jdbcType=VARCHAR}

        , STATUS_CD      = #{statusCd}

    , MODIFY_USER_ID     = #{modifyUserId}
    , MODIFY_DT          = NOW()
WHERE MKT_PROJECT_ID = #{marketingProjectId}

mapper.delete:
/* 마케팅 프로젝트 삭제 marketing.deleteMarketingProject */
DELETE FROM TB_MKT_PROJECT
WHERE MKT_PROJECT_ID = #{marketingProjectId}

mapper.insert:
/* 마케팅 파일 등록 marketing.insertMarketingFile */
INSERT INTO TB_MKT_FILE (
    MKT_FILE_ID
    , MKT_PROJECT_ID
    , FILE_PATH
    , FILE_NM
    , FILE_SIZE
    , FILE_TYPE
    , CREATE_USER_ID
    , CREATE_DT
) VALUES (
    #{marketingFileId}
    , #{marketingProjectId, jdbcType=VARCHAR}
    , #{filePath}
    , #{fileNm}
    , #{fileSize}
    , #{fileType}
    , #{createUserId}
    , NOW()
)

mapper.update:
/* 마케팅 첨부파일명 수정 marketing.updateMarketingFile */
UPDATE TB_MKT_FILE SET
    FILE_NM = #{fileNm}
WHERE MKT_FILE_ID = #{marketingFileId}

mapper.delete:
/* 마케팅 첨부파일 삭제 marketing.deleteMarketingFile */
DELETE FROM TB_MKT_FILE
WHERE MKT_FILE_ID = #{marketingFileId}

mapper.select:
/* 마케팅 콘텐츠 목록 조회 marketing.selectMarketingList */ SELECT m.MKT_ID AS MKT_ID , m.MKT_PROJECT_ID AS MARKETING_PROJECT_ID , m.AGENT_ID AS AGENT_ID , m.TITLE AS TITLE , m.OUTPUT_MODE AS OUTPUT_MODE , m.STATUS_CD AS STATUS_CD , m.CONTENT_TYPE AS CONTENT_TYPE , m.REQUEST_JSON AS REQUEST_JSON , DATE_FORMAT(m.PUBLISH_SCHEDULED_DT, '%Y-%m-%d %H:%i:%s') AS PUBLISH_SCHEDULED_DT , m.PUBLISHED_YN AS PUBLISHED_YN , u.USER_NM AS CREATE_USER_NM , DATE_FORMAT(m.CREATE_DT, '%Y-%m-%d %H:%i:%s') AS CREATE_DT FROM TB_MKT m LEFT JOIN TB_USER u ON u.USER_ID = m.CREATE_USER_ID WHERE 1 = 1 AND m.MKT_PROJECT_ID = #{marketingProjectId}
AND m.TITLE LIKE CONCAT('%', #{keyword}, '%')
AND m.CONTENT_TYPE = #{contentType}
AND m.OUTPUT_MODE = #{outputMode}
AND m.CREATE_DT >= DATE_SUB(NOW(), INTERVAL #{periodDays} DAY)
ORDER BY COALESCE(m.MODIFY_DT, m.CREATE_DT) DESC, m.CREATE_DT DESC

mapper.insert:
/* 마케팅 콘텐츠 등록 marketing.insertMarketing */
INSERT INTO TB_MKT (
    MKT_ID
    , USER_ID
    , MKT_PROJECT_ID
    , AGENT_ID
    , TITLE
    , OUTPUT_MODE
    , STATUS_CD
    , CONTENT_TYPE
    , REQUEST_JSON
    , CREATE_USER_ID
    , MODIFY_USER_ID
    , CREATE_DT
) VALUES (
    #{mktId}
    , #{userId}
    , #{marketingProjectId}
    , #{agentId}
    , #{title}
    , #{outputMode}
    , #{statusCd}
    , #{contentType}
    , #{requestJson, jdbcType=LONGVARCHAR}
    , #{createUserId}
    , #{modifyUserId}
    , NOW()
)

mapper.update:
/* 마케팅 콘텐츠 제목 수정 marketing.updateMarketingTitle */
UPDATE TB_MKT SET
    TITLE               = #{title}
    , MODIFY_USER_ID    = #{modifyUserId}
    , MODIFY_DT         = NOW()
WHERE MKT_ID = #{mktId}

/* 마케팅 콘텐츠 생성 상태 수정 marketing.updateMarketingStatus */
UPDATE TB_MKT SET
    STATUS_CD           = #{statusCd}
    , MODIFY_USER_ID    = #{modifyUserId}
    , MODIFY_DT         = NOW()
WHERE MKT_ID = #{mktId}

/* 발행 예정일 지정/변경 marketing.updateMarketingSchedule */
UPDATE TB_MKT SET
    PUBLISH_SCHEDULED_DT = #{publishScheduledDt, jdbcType=TIMESTAMP}
    , PUBLISHED_YN       = 'N'
    , MODIFY_USER_ID     = #{modifyUserId}
    , MODIFY_DT          = NOW()
WHERE MKT_ID = #{mktId}

/* 발행 완료 표시/해제 marketing.updateMarketingPublished */
UPDATE TB_MKT SET
    PUBLISHED_YN     = #{publishedYn}
    , MODIFY_USER_ID = #{modifyUserId}
    , MODIFY_DT      = NOW()
WHERE MKT_ID = #{mktId}

/* 마케팅 콘텐츠 수정일 갱신 (시안 수정 시) marketing.touchMarketing */
UPDATE TB_MKT SET
    MODIFY_USER_ID      = #{modifyUserId}
    , MODIFY_DT         = NOW()
WHERE MKT_ID = #{mktId}

mapper.insert:
/* 마케팅 콘텐츠 시안 등록 marketing.insertMarketingContent */
INSERT INTO TB_MKT_CONTENT (
    MKT_CONTENT_ID
    , MKT_ID
    , CONTENT_NO
    , RECOMMEND_YN
    , CONTENT_LABEL
    , TEXT_CONTENT
    , IMAGE_FILE
    , CREATE_USER_ID
    , CREATE_DT
) VALUES (
    #{mktContentId}
    , #{mktId}
    , #{contentNo}
    , #{recommendYn}
    , #{contentLabel, jdbcType=VARCHAR}
    , #{textContent, jdbcType=LONGVARCHAR}
    , #{imageFile, jdbcType=LONGVARCHAR}
    , #{createUserId}
    , NOW()
)

mapper.update:
/* 마케팅 콘텐츠 시안 수정(수정된 필드만 직전 값 백업, 안 바뀐 필드는 백업 비움) marketing.updateMarketingContent */
UPDATE TB_MKT_CONTENT SET
    MODIFY_USER_ID     = #{modifyUserId}
    , MODIFY_DT        = NOW()

        , PREV_TEXT_CONTENT = TEXT_CONTENT
        , TEXT_CONTENT      = #{textContent, jdbcType=LONGVARCHAR}
        , PREV_IMAGE_FILE   = NULL


        , PREV_IMAGE_FILE   = IMAGE_FILE
        , IMAGE_FILE        = #{imageFile, jdbcType=LONGVARCHAR}
        , PREV_TEXT_CONTENT = NULL

WHERE MKT_CONTENT_ID = #{mktContentId}
    AND MKT_ID = #{mktId}

/* 시안 직전 버전으로 되돌리기(백업 없는 필드는 현재값 유지) marketing.restoreMarketingContentPrevious */
UPDATE TB_MKT_CONTENT SET
    TEXT_CONTENT        = COALESCE(PREV_TEXT_CONTENT, TEXT_CONTENT)
    , IMAGE_FILE        = COALESCE(PREV_IMAGE_FILE, IMAGE_FILE)
    , PREV_TEXT_CONTENT = NULL
    , PREV_IMAGE_FILE   = NULL
    , MODIFY_USER_ID    = #{modifyUserId}
    , MODIFY_DT         = NOW()
WHERE MKT_CONTENT_ID = #{mktContentId}
    AND MKT_ID = #{mktId}
    AND (PREV_TEXT_CONTENT IS NOT NULL OR PREV_IMAGE_FILE IS NOT NULL)

mapper.delete:
/* 프로젝트 소속 콘텐츠 시안 전체 삭제 marketing.deleteMarketingContentsByProject */
DELETE FROM TB_MKT_CONTENT
WHERE MKT_ID IN (SELECT MKT_ID FROM TB_MKT WHERE MKT_PROJECT_ID = #{marketingProjectId})
